export function createOrderPhotos({db,root,state,esc,notice}){
 const queues=new Map();let generation=0,context='';
 const identity=()=>`${state().user?.id||''}/${state().storeId||''}/${state().shift?.id||''}`;
 function release(item){URL.revokeObjectURL(item.url);}
 function clear(){generation++;for(const list of queues.values())list.forEach(release);queues.clear();context=identity();}
 function scope(){if(context!==identity())clear();}
 function get(key){scope();if(!queues.has(key))queues.set(key,[]);return queues.get(key);}
 function markup(key){return `<div class="order-photo-composer" data-photo-composer="${esc(key)}"><div class="photo-composer-heading"><strong>Fotos del pedido <span class="muted small">(opcional)</span></strong><span data-photo-progress class="small" role="status"></span></div><div class="photo-composer-actions"><button type="button" class="secondary" data-photo-pick="gallery">Galería</button><button type="button" class="secondary" data-photo-pick="camera">Tomar foto</button></div><input type="file" accept="image/jpeg,image/png,image/webp" multiple data-photo-files="gallery" hidden><input type="file" accept="image/*" capture="environment" data-photo-files="camera" hidden><div class="order-photo-previews" data-photo-previews></div></div>`;}
 function paint(composer){if(!composer?.isConnected)return;const list=get(composer.dataset.photoComposer),save=composer.closest('form')?.querySelector('[data-photo-save]');if(save)save.disabled=!list.length;composer.querySelector('[data-photo-previews]').innerHTML=list.map((p,i)=>`<figure><img src="${esc(p.url)}" alt="Foto ${i+1} del pedido"><button type="button" data-photo-remove="${i}" aria-label="Quitar foto ${i+1}">×</button><figcaption>${esc(p.name)}</figcaption></figure>`).join('');}
 function mount(container=root){container.querySelectorAll('[data-photo-composer]').forEach(paint);}
 async function prepare(file){if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10*1024*1024)throw Error('Usa fotos JPEG, PNG o WebP de hasta 10 MB.');
  let bitmap;try{bitmap=await createImageBitmap(file);}catch{throw Error('No se pudo leer la foto. Elige otra imagen.');}
  try{if(!bitmap.width||!bitmap.height||bitmap.width*bitmap.height>60000000)throw Error('La resolución de la foto es demasiado grande.');const scale=Math.min(1,1600/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.8));if(!blob||blob.size>2*1024*1024)throw Error('No se pudo comprimir la foto.');const hash=[...new Uint8Array(await crypto.subtle.digest('SHA-256',await blob.arrayBuffer()))].map(b=>b.toString(16).padStart(2,'0')).join('');return {blob,hash,name:file.name||'Foto del pedido',url:URL.createObjectURL(blob)};}finally{bitmap.close();}
 }
 async function input(event){const input=event.target;if(!input.hasAttribute('data-photo-files')||event.type!=='change')return false;const composer=input.closest('[data-photo-composer]'),key=composer.dataset.photoComposer,files=[...input.files],list=get(key),run=generation;input.value='';if(files.length+list.length>5)throw Error('Adjunta hasta 5 fotos por envío.');
  composer.dataset.preparing='1';composer.querySelectorAll('button').forEach(b=>b.disabled=true);composer.querySelector('[data-photo-progress]').textContent='Preparando fotos…';
  try{for(const file of files){const prepared=await prepare(file);if(run!==generation){release(prepared);return true;}if(list.some(p=>p.hash===prepared.hash))release(prepared);else list.push(prepared);}paint(composer);composer.dispatchEvent(new Event('change',{bubbles:true}));}
  finally{if(composer.isConnected){if(run===generation)paint(composer);delete composer.dataset.preparing;composer.querySelectorAll('button').forEach(b=>b.disabled=false);composer.querySelector('[data-photo-progress]').textContent='';}}return true;
 }
 function click(button){const composer=button.closest('[data-photo-composer]');if(!composer)return false;if(button.hasAttribute('data-photo-pick')){composer.querySelector(`[data-photo-files="${button.dataset.photoPick}"]`).click();return true;}if(button.hasAttribute('data-photo-remove')){const list=get(composer.dataset.photoComposer),index=Number(button.dataset.photoRemove),item=list[index];if(item){release(item);list.splice(index,1);paint(composer);composer.dispatchEvent(new Event('change',{bubbles:true}));}return true;}return false;}
 function transfer(from,to){const list=get(from);if(!list.length)return;const target=get(to);for(const item of list){if(target.some(p=>p.hash===item.hash))release(item);else target.push(item);}queues.set(from,[]);}
 async function upload(orderId){const list=get(orderId),run=generation,owner=state().user?.id;let uploaded=0;
  for(const item of [...list]){if(run!==generation||state().user?.id!==owner)throw Error('La sesión cambió. Vuelve a abrir el pedido.');const progress=root.querySelector(`[data-photo-composer="${orderId}"] [data-photo-progress]`)||root.querySelector('[data-photo-composer="new"] [data-photo-progress]');if(progress)progress.textContent=`Guardando foto ${uploaded+1}…`;const r=await db.storage.from('charito-orders').upload(`${orderId}/${item.hash}.jpg`,item.blob,{contentType:'image/jpeg',upsert:false});if(r.error&&String(r.error.statusCode)!=='409')throw Error('No se pudo adjuntar una foto. '+r.error.message);if(run!==generation||state().user?.id!==owner)throw Error('La sesión cambió.');const index=list.indexOf(item);if(index>=0)list.splice(index,1);release(item);uploaded++;}return uploaded;
 }
 async function list(orderId,target){if(!target)return;const run=generation,owner=state().user?.id,r=await db.storage.from('charito-orders').list(orderId,{limit:100});if(!target.isConnected||run!==generation||owner!==state().user?.id)return;
  if(r.error){target.innerHTML='<p class="warn">No se pudieron consultar las fotos. Comprueba el almacenamiento privado de pedidos.</p>';return;}
  const photos=await Promise.all((r.data||[]).filter(f=>f.id).map(async file=>{const signed=await db.storage.from('charito-orders').createSignedUrl(`${orderId}/${file.name}`,300);return signed.data?.signedUrl?`<a href="${esc(signed.data.signedUrl)}" target="_blank" rel="noopener"><img src="${esc(signed.data.signedUrl)}" alt="Foto del pedido" loading="lazy"></a>`:'';}));if(target.isConnected&&run===generation&&owner===state().user?.id)target.innerHTML=photos.join('')||'<p class="muted small">Sin fotos adjuntas.</p>';
 }
 function drop(key){const list=queues.get(key);if(list)list.forEach(release);queues.delete(key);}
 return {markup,mount,input,click,transfer,upload,list,clear,drop,count:key=>get(key).length,preparing:()=>!!root.querySelector('[data-photo-composer][data-preparing]')};
}
